#!/bin/bash
# Name: Classic 98 Theme
# Description: The Mike OS look in classic grey: grey taskbar, start button and start menu, navy blue window title bars and a solid teal wallpaper. Switch it on and off any time in the Themes app.
# Category: Themes
# Icon: preferences-desktop-theme
# Check: /usr/share/mikeos-amber/themes/classic-98/theme.json
# Uninstall-Args: --uninstall
# Size: ~100 KB
#
# Classic 98 theme for Mike OS: Amber (works on the full desktop and on Amber Lite).
# Also installs the Themes app if this computer doesn't have it yet.
set -u
USER_NAME=${SUDO_USER:-amber}; [ "$USER_NAME" = root ] && USER_NAME=amber
USER_HOME=$(getent passwd "$USER_NAME" | cut -d: -f6)

desktop_env() {   # the logged-in desktop's environment, so theme changes reach it
    local pid v val
    pid=$(pgrep -u "$USER_NAME" -x plasmashell | head -n 1)
    [ -z "$pid" ] && pid=$(pgrep -u "$USER_NAME" -x lxqt-panel | head -n 1)
    [ -z "$pid" ] && return 1
    for v in DISPLAY XAUTHORITY DBUS_SESSION_BUS_ADDRESS XDG_RUNTIME_DIR XDG_CURRENT_DESKTOP XDG_CONFIG_HOME; do
        val=$(tr '\0' '\n' < "/proc/$pid/environ" | grep "^$v=" | head -n 1)
        [ -n "$val" ] && printf '%s\n' "$val"
    done
}

if [ "${1:-}" = "--uninstall" ]; then
    # if Classic 98 is in use, put Amber back first
    if [ "$(cat "$USER_HOME/.config/mikeos-amber/theme" 2>/dev/null)" = classic-98 ]; then
        echo "STATUS:Switching back to the Amber theme..."
        mapfile -t envs < <(desktop_env)
        sudo -u "$USER_NAME" env HOME="$USER_HOME" "${envs[@]}" python3 /usr/share/mikeos-amber/apps/themes.py --apply amber \
            >/dev/null 2>&1 < /dev/null || true
    fi
    rm -rf /usr/share/mikeos-amber/themes/classic-98 /usr/share/lxqt/themes/classic-98 /usr/share/themes/Classic-98 \
           /usr/share/color-schemes/Classic98.colors /usr/share/wallpapers/MikeOS-Classic-98 /usr/share/plasma/desktoptheme/mikeos-classic-98
    echo "Classic 98 theme removed."
    exit 0
fi

echo "STATUS:Installing the Classic 98 theme..."
T=$(mktemp -d)
mkdir -p "$T/theme" "$T/app"
base64 -d <<'C98_THEME_PAYLOAD' | tar -xzf - -C "$T/theme" || { echo "ERROR: the theme file is damaged - try again."; exit 1; }
